            List<int> scores = new List<int> { 12, 15, 18, 14 };
            Console.WriteLine(Average(scores));
        }

        static double Average(List<int> scores)
        {
            int total = 0;
            for (int i = 0; i <= scores.Count; i++)
            {
                total = total + scores[i];
            }
            return total / scores.Count;
        }
    }
}

