using System;
using System.Collections.Generic;

namespace MyProgram
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Class Quiz Score Analyser");
            List<int> scores = GetScores();

            if (scores.Count == 0)
            {
                Console.WriteLine("No scores entered.");
            }
            else
            {
                Console.WriteLine("Scores entered: " + scores.Count);
                Console.WriteLine("Average: " + CalculateAverage(scores));
                Console.WriteLine("Highest: " + FindHighest(scores));
                Console.WriteLine("Passed (10 or more): " + CountPasses(scores, 10));
            }
        }

        static List<int> GetScores()
        {
            List<int> scores = new List<int>();
            bool finished = false;

            while (finished == false)
            {
                Console.WriteLine("Enter a score out of 20 (or -1 to finish):");
                string input = Console.ReadLine();
                int score;

                if (int.TryParse(input, out score) == false)
                {
                    Console.WriteLine("That is not a whole number. Try again.");
                }
                else if (score == -1)
                {
                    finished = true;
                }
                else if (score < 0 || score > 20)
                {
                    Console.WriteLine("Scores must be from 0 to 20. Try again.");
                }
                else
                {
                    scores.Add(score);
                }
            }

            return scores;
        }

        static double CalculateAverage(List<int> scores)
        {
            int total = 0;
            foreach (int score in scores)
            {
                total = total + score;
            }
            return (double)total / scores.Count;
        }

        static int FindHighest(List<int> scores)
        {
            int highest = scores[0];
            foreach (int score in scores)
            {
                if (score > highest)
                {
                    highest = score;
                }
            }
            return highest;
        }

        static int CountPasses(List<int> scores, int passMark)
        {
            int passes = 0;
            foreach (int score in scores)
            {
                if (score >= passMark)
                {
                    passes++;
                }
            }
            return passes;
        }
    }
}
